MEMORIES = [
    {'name': 'book_one_meeting', 'description': "Requests to put exactly one meeting on this week's calendar with named people, a length, a day window and usually a start or end limit. They may be chatty, terse or in shorthand ('grab 30 min', 'sched req: ...', 'need slot this wk', 'one mtg'). Not this kind: requests for two meetings or 'twice', requests that only ask for availability or say not to book, and cancel, move, hold or draft requests.", 'route': 'program', 'read_only': False, 'body': 'ROSTER = ["Dana Park", "Omar Haddad", "Sam Ortiz", "Priya Shah", "Leo Chen", "Ana Silva"]
DAYS = ["mon", "tue", "wed", "thu", "fri"]
DAY_NAMES = {"mon": "Monday", "tue": "Tuesday", "wed": "Wednesday", "thu": "Thursday", "fri": "Friday"}
TITLES = ["Launch review", "Planning session", "Project sync", "Budget check-in", "Design review", "Hiring debrief"]
STD_MINUTES = [30, 45, 60]
BOOK_MEMORY = (
    "To book one meeting: call find_shared_starts(attendees, days, minutes, earliest, latest_end) with only the "
    "days in the requested window (lowercase mon..fri), earliest as HH:MM for 'no earlier than' wording else '', "
    "latest_end as HH:MM for 'wrapped up by' wording else ''. The user Maya Rivera is added automatically. "
    "The procedure already accounts for calendars, time zones and notes such as Dana's 15-minute buffer, so do "
    "not read calendars by hand. Then book_time once with the earliest day in week order that has starts and its "
    "first start, the meeting topic as title, the same minutes, and full attendee names. Roster: Dana Park, Omar "
    "Haddad, Sam Ortiz, Priya Shah, Leo Chen, Ana Silva. If no starts come back, do not book outside the "
    "constraints; tell the user."
)
MANY_MEMORY = (
    " For several meetings: one find_shared_starts call, then one book_time per meeting, each on a different "
    "day when the request says so, taking days in week order and each day's first start."
)
RO_MEMORY = (
    "This request does not ask to book a new meeting now. Do not book, cancel or change anything; answer from "
    "the read tools if useful. A past run was rejected for booking a meeting nobody asked for."
)


def hand(why, route, memory, read_only):
    out = {"handoff": why, "route": route, "memory": memory}
    if read_only:
        out["read_only"] = True
    return out


def get_noul(ans, key):
    try:
        v = ans[key]["noul"]
        return float(v)
    except Exception:
        return None


def get_choice(ans, key):
    try:
        a = ans[key]
        return str(a["choice"]), float(a["confidence"])
    except Exception:
        return None, 0.0


def to_minutes(hhmm):
    try:
        parts = str(hhmm).strip().split(":")
        if len(parts) != 2:
            return None
        h = int(parts[0])
        m = int(parts[1])
        if h < 0 or h > 23 or m < 0 or m > 59:
            return None
        return h * 60 + m
    except Exception:
        return None


def fmt_time(total):
    h, m = divmod(total, 60)
    return ("0" if h < 10 else "") + str(h) + ":" + ("0" if m < 10 else "") + str(m)


async def decide(request, kit):
    text = str(request)
    low = text.lower()
    try:
        found = [str(x) for x in kit.find("\\d{1,2}:\\d{2}|\\d+", text)]
    except Exception:
        return hand("could not scan the request", "medium", BOOK_MEMORY, False)
    time_cands = []
    for f in found:
        if ":" in f and to_minutes(f) is not None and f not in time_cands:
            time_cands.append(f)
    found_minutes = []
    for f in found:
        if ":" not in f:
            try:
                n = int(f)
            except Exception:
                continue
            if 5 <= n <= 480 and n not in found_minutes:
                found_minutes.append(n)
    minute_opts = list(found_minutes)
    for n in STD_MINUTES:
        if n not in minute_opts:
            minute_opts.append(n)

    q = {}
    q["intent"] = {
        "type": "choice",
        "instructions": "What does `request` ask the calendar assistant to do?",
        "criteria": {
            "book_one": "put exactly one new meeting on the calendar (book, schedule, set up, grab or find a slot for it)",
            "book_several": "put two or more new meetings on the calendar (two, twice, several sessions)",
            "ask_or_change": "only asks about a meeting or availability, is hypothetical, says not to book, or asks to cancel, move, hold off or draft",
            "unrelated": "something that is not scheduling a meeting (documents, lunch, expenses, messages, etc.)",
        },
    }
    q["no_booking"] = {
        "type": "noul",
        "instructions": "Does `request` NOT want a new meeting put on the calendar now, because it only wants availability or information, is hypothetical, says not to book, asks to cancel, move, hold or draft, or is about some other task? A request to book, schedule, set up, grab or find a slot for a meeting wants it booked: answer no for those.",
    }
    q["several"] = {
        "type": "noul",
        "instructions": "Does `request` ask for more than one meeting to be booked (for example two meetings, twice, two sessions)?",
    }
    for i, name in enumerate(ROSTER):
        q["att_" + str(i)] = {
            "type": "noul",
            "instructions": "Is " + name + " (possibly given by first name only) one of the people `request` asks to include in the meeting to be booked?",
        }
    q["other_people"] = {
        "type": "noul",
        "instructions": "Does `request` name as a meeting attendee any person who is not in this list: " + ", ".join(ROSTER) + "? The user (Maya Rivera, 'me') does not count, and people merely mentioned in background chatter do not count.",
    }
    for d in DAYS:
        q["day_" + d] = {
            "type": "noul",
            "instructions": "Is " + DAY_NAMES[d] + " one of the days on which `request` allows the meeting to be held? A range such as 'Tuesday to Thursday' includes every day in between, and a preferred window counts as the allowed window. If the request names no particular days of this week, answer yes.",
        }
    day_crit = {}
    for d in DAYS:
        day_crit[d] = DAY_NAMES[d]
    day_crit["none"] = "the request names no particular days"
    q["first_day"] = {
        "type": "choice",
        "instructions": "Which is the earliest weekday in the window of days `request` allows for the meeting?",
        "criteria": day_crit,
    }
    q["last_day"] = {
        "type": "choice",
        "instructions": "Which is the latest weekday in the window of days `request` allows for the meeting?",
        "criteria": day_crit,
    }
    min_crit = {}
    for n in minute_opts:
        min_crit[str(n)] = "the meeting should last " + str(n) + " minutes"
    min_crit["none"] = "the request states no meeting length, or a length not listed"
    q["minutes"] = {
        "type": "choice",
        "instructions": "How long should the meeting in `request` last, in minutes?",
        "criteria": min_crit,
    }
    q["has_earliest"] = {
        "type": "noul",
        "instructions": "Does `request` set an earliest time of day before which the meeting must not start (for example 'no earlier than', 'nothing before', 'starting X or later')?",
    }
    q["has_latest"] = {
        "type": "noul",
        "instructions": "Does `request` set a time of day by which the meeting must be finished (for example 'wrapped up by', 'done by', 'over by', 'finished before')?",
    }
    for i, c in enumerate(time_cands[:4]):
        q["time_" + str(i)] = {
            "type": "choice",
            "instructions": "In `request`, what does the clock time " + c + " mean for the meeting to be booked?",
            "criteria": {
                "earliest_start": "the meeting must not start before " + c + " (start at " + c + " or later)",
                "latest_end": "the meeting must be finished by " + c,
                "exact_start": "the meeting must start exactly at " + c,
                "other": "something else, or it is not about the meeting to be booked",
            },
        }
    t_crit = {}
    for t in TITLES:
        t_crit[t] = "the meeting to book is a " + t.lower()
    t_crit["other"] = "the meeting has some other topic, or no topic is given"
    q["title"] = {
        "type": "choice",
        "instructions": "What is the topic of the meeting `request` asks to book?",
        "criteria": t_crit,
    }
    q["extra"] = {
        "type": "noul",
        "instructions": "Does `request` require any of these for the meeting: a recurring series, a week other than this week, a specific room or location, or particular times of day to avoid other than an earliest start or a latest finish? Emphasis, politeness and background chatter do not count.",
    }

    try:
        ans = await kit.ask({"request": text, "user": "Maya Rivera"}, q)
    except Exception:
        return hand("could not get judgments", "medium", BOOK_MEMORY, False)
    if not isinstance(ans, dict):
        return hand("could not get judgments", "medium", BOOK_MEMORY, False)

    intent, iconf = get_choice(ans, "intent")
    nb = get_noul(ans, "no_booking")
    sv = get_noul(ans, "several")
    if intent is None or nb is None or sv is None:
        return hand("unclear what is asked", "medium", BOOK_MEMORY, False)
    if intent in ("ask_or_change", "unrelated") and iconf >= 0.5 and nb > 0.7:
        return hand("not a request to book a meeting now", "low", RO_MEMORY, True)
    if intent == "book_several" and sv > 0.7 and nb < 0.5:
        return hand("more than one meeting requested", "medium", BOOK_MEMORY + MANY_MEMORY, False)
    if not (intent == "book_one" and nb < 0.5 and sv < 0.5):
        return hand("unclear whether one meeting should be booked", "medium", BOOK_MEMORY + MANY_MEMORY, False)

    def fail(why):
        return hand(why, "low", BOOK_MEMORY, False)

    # attendees
    op = get_noul(ans, "other_people")
    if op is None or op >= 0.5:
        return fail("attendees may include someone outside the known roster")
    picked = []
    for i, name in enumerate(ROSTER):
        p = get_noul(ans, "att_" + str(i))
        if p is None:
            return fail("attendee judgment missing")
        pos = low.find(name.split(" ")[0].lower())
        if pos < 0:
            if p > 0.7:
                return fail("attendee judgment does not match the request text")
            continue
        if p > 0.7:
            picked.append((pos, name))
        elif p >= 0.3:
            return fail("unsure whether " + name + " attends")
    if not picked:
        return fail("no attendees identified")
    attendees = [n for (pos, n) in sorted(picked)]
    for name in attendees:
        try:
            r = kit.read("read_calendar", person=name, day="mon")
        except Exception:
            return fail("could not verify attendee " + name)
        if not isinstance(r, dict) or "error" in r or r.get("person") != name:
            return fail("could not verify attendee " + name)

    # days
    fd, fconf = get_choice(ans, "first_day")
    ld, lconf = get_choice(ans, "last_day")
    if fd is not None and fd not in DAYS and fd != "none":
        fd = None
    if ld is not None and ld not in DAYS and ld != "none":
        ld = None
    days = []
    for d in DAYS:
        p = get_noul(ans, "day_" + d)
        if p is None:
            return fail("unsure about the day window")
        if p > 0.7:
            days.append(d)
        elif p >= 0.3:
            if fd in DAYS and ld in DAYS and fconf >= 0.6 and lconf >= 0.6:
                if DAYS.index(fd) <= DAYS.index(d) <= DAYS.index(ld):
                    days.append(d)
            else:
                return fail("unsure about the day window")
    if not days:
        return fail("no days identified")
    if len(days) == 5:
        ok_all = (fd == "none" and ld == "none") or (fd == "mon" and ld == "fri")
        if not ok_all:
            return fail("day window judgments disagree")
    else:
        if fd is not None and fconf >= 0.6 and fd != days[0]:
            return fail("day window judgments disagree")
        if ld is not None and lconf >= 0.6 and ld != days[-1]:
            return fail("day window judgments disagree")

    # minutes
    mc, mconf = get_choice(ans, "minutes")
    if mc is None or mc == "none":
        return fail("meeting length unclear")
    try:
        minutes = int(mc)
    except Exception:
        return fail("meeting length unclear")
    if minutes not in minute_opts:
        return fail("meeting length unclear")
    if minutes in found_minutes:
        if mconf < 0.4:
            return fail("meeting length unclear")
    elif mconf < 0.6:
        return fail("meeting length unclear")

    # time limits
    he = get_noul(ans, "has_earliest")
    hl = get_noul(ans, "has_latest")
    if he is None or hl is None:
        return fail("time limits unclear")
    if len(time_cands) > 4:
        return fail("too many times in the request")
    e_num = None
    l_num = None
    for i, c in enumerate(time_cands):
        role, rconf = get_choice(ans, "time_" + str(i))
        if role is None or rconf < 0.5:
            return fail("meaning of " + c + " unclear")
        if role == "earliest_start":
            if e_num is not None:
