async def decide(request, kit):
    try:
        recalled = await kit.recall(request, 6)
    except Exception:
        recalled = []
    candidates = []
    seen = set()
    for item in recalled or []:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        if not isinstance(name, str) or not name or name in seen:
            continue
        seen.add(name)
        candidates.append(item)
    if not candidates:
        return {"handoff": "no stored memory was recalled for this request"}

    names = [c["name"] for c in candidates]
    first = names[0]

    shown = []
    criteria = {}
    for c in candidates:
        read_only = bool(c.get("read_only"))
        description = str(c.get("description", ""))
        if read_only:
            act_text = "read_only true: cannot act, only reads and answers"
        else:
            act_text = "read_only false: can act and book"
        shown.append({
            "name": c["name"],
            "description": description,
            "read_only": read_only,
            "can_act": not read_only,
        })
        criteria[c["name"]] = description + " (" + act_text + ")"

    chosen = first
    try:
        reply = await kit.ask(
            {"request": request, "candidates": shown},
            {"memory": {"type": "choice", "instructions": INSTRUCTIONS, "criteria": criteria}},
        )
        answer = reply["memory"]["choice"]
        if isinstance(answer, str) and answer in names:
            chosen = answer
    except Exception:
        chosen = first

    return {"serve": chosen}

