def hand(why, route, memory, read_only):
    out = {"handoff": why, "route": route, "memory": memory}
    if read_only:
        out["read_only"] = True
    return out


def get_noul(ans, key):
    try:
        v = ans[key]["noul"]
        return float(v)
    except Exception:
        return None


def get_choice(ans, key):
    try:
        a = ans[key]
        return str(a["choice"]), float(a["confidence"])
    except Exception:
        return None, 0.0


def to_minutes(hhmm):
    try:
        parts = str(hhmm).strip().split(":")
        if len(parts) != 2:
            return None
        h = int(parts[0])
        m = int(parts[1])
        if h < 0 or h > 23 or m < 0 or m > 59:
            return None
        return h * 60 + m
    except Exception:
        return None


def fmt_time(total):
    h, m = divmod(total, 60)
    return ("0" if h < 10 else "") + str(h) + ":" + ("0" if m < 10 else "") + str(m)


async def decide(request, kit):
